'use strict';
const canvas=document.getElementById('game'),overlay=document.getElementById('overlay'),ctx=overlay.getContext('2d'),$=id=>document.getElementById(id),W=960,H=540;
let renderer;const combatAudio=new CombatAudio();
const killLines=['Back to hell!','Stay down, demon!','That’s what you get!','Burn in hell!'];
const WEAPONS=[{name:'REVOLVER',delay:.3,damage:38,cone:.065,size:330},{name:'SHOTGUN',delay:.8,damage:125,cone:.19,size:390},{name:'HEAVY MACHINE GUN',delay:.115,damage:32,cone:.08,size:440}];
const exit={x:18,y:2.2};
const clamp=(v,a,b)=>Math.max(a,Math.min(b,v)),angle=a=>Math.atan2(Math.sin(a),Math.cos(a));
let p,enemies=[],items=[],seals=[],shots=[],particles=[],splats=[],ammo,weapon=0,ownsHeavy=false,mode='menu',time=0,kills=0,cooldown=0,flash=0,hurt=0,notice=0,lastQuip=-10,quipIndex=-1,quipTimer=0,finalWave=false,gateProgress=0,mapShown=false,keys={},mouse={left:false,right:false},last=0,sound=true,audio;
function demon(x,y,type=0){return{x,y,z:floorAt(x,y),type,hp:[65,85,280][type],cd:1+Math.random(),hit:0}}
function reset(){
 resetWorld();renderer?.rebuildWorld(level,floorAt,ceilingAt);p={x:16,y:28.4,z:0,eyeZ:0,a:-Math.PI/2,pitch:0,hp:100};
 enemies=[[14,24,0],[19,23,0],[7,20,0],[9,14,1],[24,15,1],[23,20,0],[7,27,0],[24,27,1],[16,16,2],[10,4,1],[22,4,1],[18,5,2],[37,16,0],[43,17,1],[40,27,0],[35,32,1],[44,32,0],[40,31,2]].map(e=>demon(...e));
 items=[{x:7,y:28,type:'health'},{x:24,y:28,type:'ammo'},{x:6,y:15,type:'ammo'},{x:25,y:15,type:'health'},{x:11,y:20,type:'health'},{x:21,y:20,type:'ammo'},{x:5.6,y:23.5,type:'secret'},{x:2.5,y:21.5,type:'heavy'},{x:2.5,y:23,type:'secret'},{x:30.5,y:27.5,type:'secret'},{x:35,y:16,type:'ammo'},{x:44,y:16,type:'health'},{x:40,y:25.5,type:'ammo'},{x:35,y:30,type:'health'},{x:44,y:30,type:'ammo'},{x:7,y:2,type:'ammo'},{x:24,y:2,type:'health'}];
 seals=[{x:7,y:14.5,on:true},{x:16,y:19.5,on:true},{x:39.5,y:30.5,on:true}];
 shots=[];particles=[];splats=[];ammo=[64,24,0];weapon=0;ownsHeavy=false;time=kills=cooldown=flash=hurt=notice=quipTimer=gateProgress=0;lastQuip=-10;finalWave=false;mapShown=false;keys={};mouse={left:false,right:false};combatAudio.stopVoice();for(let id of ['message','interact','quip'])$(id).textContent='';hud();
}
function tone(f=100,d=.1,type='sawtooth',vol=.08){if(!sound||!audio)return;let o=audio.createOscillator(),g=audio.createGain();o.type=type;o.frequency.setValueAtTime(f,audio.currentTime);o.frequency.exponentialRampToValueAtTime(Math.max(20,f/3),audio.currentTime+d);g.gain.setValueAtTime(vol,audio.currentTime);g.gain.exponentialRampToValueAtTime(.001,audio.currentTime+d);o.connect(g);g.connect(audio.destination);o.start();o.stop(audio.currentTime+d)}
function tell(text){$('message').textContent=text;notice=3}
function finish(win){combatAudio.stopVoice();combatAudio.setGameplayActive(false);mode=win?'won':'dead';document.exitPointerLock?.();$('veil').style.display='flex';$('crosshair').style.display='none';$('interact').textContent='';document.querySelector('.eyebrow').textContent=win?'YOU MADE IT THROUGH HELL.':'HELL CAUGHT UP WITH YOU.';document.querySelector('h1').innerHTML=win?'THE GATE<br><em>IS OPEN</em>':'YOU ARE<br><em>DEAD</em>';$('description').textContent=win?`${kills} demons killed · ${secretsFound}/2 secrets · ${Math.floor(time/60)}m ${Math.floor(time%60)}s. You are free.`:'The seals are still waiting. Pick up your weapon.';$('play').textContent='TRY AGAIN →';$('hint').textContent='ONE MORE TRY. ONE MORE CHANCE.'}
function verticalHit(e){const d=Math.hypot(e.x-p.x,e.y-p.y),height=e.type===2?2.2:1.65,aim=p.z+1.05+Math.tan(p.pitch)*d;return aim>e.z-.08&&aim<e.z+height}
function selectWeapon(index){if(index===2&&!ownsHeavy){tell('The heavy machine gun is hidden in a secret passage.');return}weapon=index;hud()}
function shoot(){if(mode!=='playing'||cooldown>0)return;if(ammo[weapon]<=0){tell('Out of ammo — switch weapons [1 / 2 / 3]');cooldown=.3;return}const w=WEAPONS[weapon];ammo[weapon]--;cooldown=w.delay;flash=weapon===2?.08:.14;combatAudio.shot(weapon);let targets=enemies.filter(e=>e.hp>0&&verticalHit(e)&&line(p.x,p.y,e.x,e.y,p.z+1.05,e.z+.85)&&Math.abs(angle(Math.atan2(e.y-p.y,e.x-p.x)-p.a))<w.cone+.12/Math.hypot(e.x-p.x,e.y-p.y)).sort((a,b)=>Math.hypot(a.x-p.x,a.y-p.y)-Math.hypot(b.x-p.x,b.y-p.y));for(let e of targets.slice(0,weapon===1?3:1)){e.hp-=weapon===1?Math.max(30,w.damage-Math.hypot(e.x-p.x,e.y-p.y)*8):w.damage;e.hit=.15;bloodBurst(e,e.hp<=0);combatAudio.impact();if(e.hp<=0){kills++;killQuip()}}}
function bloodBurst(e,dead){const d=Math.hypot(e.x-p.x,e.y-p.y),height=clamp(p.z+1.05+Math.tan(p.pitch)*d,e.z+.3,e.z+(e.type===2?1.9:1.45));for(let i=0;i<(dead?30:14);i++){let a=Math.random()*Math.PI*2,s=.4+Math.random()*1.8;particles.push({x:e.x,y:e.y,z:height,vx:Math.cos(a)*s,vy:Math.sin(a)*s,vz:.5+Math.random()*2,size:.025+Math.random()*.055,life:1.7})}splats.push({x:e.x,y:e.y,base:e.z+.012,size:dead?.8:.4,life:28});particles=particles.slice(-240);splats=splats.slice(-70)}
function killQuip(){if(time-lastQuip<4.5)return;lastQuip=time;quipIndex=(quipIndex+1)%4;quipTimer=3;$('quip').textContent='“'+killLines[quipIndex]+'”';combatAudio.say(quipIndex)}
function updateBlood(dt){for(let b of particles){b.life-=dt;b.vz-=5.5*dt;let x=b.x+b.vx*dt,y=b.y+b.vy*dt;if(!solid(x,y)&&b.z>floorAt(x,y)){b.x=x;b.y=y}else{b.vx*=-.15;b.vy*=-.15}b.z+=b.vz*dt;let ground=floorAt(b.x,b.y)+.02;if(b.z<=ground){splats.push({x:b.x,y:b.y,base:ground,size:b.size*3,life:22});b.life=0}}particles=particles.filter(b=>b.life>0);for(let b of splats)b.life-=dt;splats=splats.filter(b=>b.life>0).slice(-70);quipTimer=Math.max(0,quipTimer-dt);if(!quipTimer)$('quip').textContent=''}
function facingSecret(){return secretDoors.find(d=>!d.opened&&!d.opening&&Math.hypot(p.x-d.x-.5,p.y-d.y-.5)<1.6&&Math.abs(angle(Math.atan2(d.y+.5-p.y,d.x+.5-p.x)-p.a))<.65&&Math.abs(p.pitch)<.75)}
function updateSecrets(dt){for(let d of secretDoors){if(!d.opening)continue;d.remaining-=dt;if(d.remaining<=0){d.opening=false;d.opened=true;secretsFound++;for(let [x,y]of d.cells)setCell(x,y,'.');renderer?.rebuildWorld(level,floorAt,ceilingAt);tell(`Secret passage discovered — ${secretsFound} / 2`)}}$('interact').textContent=mode==='playing'&&facingSecret()?'[E] Investigate cracked stone':''}
function interact(){const d=facingSecret();if(d){d.opening=true;d.remaining=.7;combatAudio.stoneDoor();tell('Ancient stone grinds open…')}}
function activateSeals(){for(let s of seals){if(!s.on||Math.hypot(s.x-p.x,s.y-p.y)>.72||Math.abs(p.z-floorAt(s.x,s.y))>.35)continue;s.on=false;tone(340,.5,'triangle',.15);tell(`Seal activated — ${seals.filter(s=>!s.on).length} / 3`)}if(!finalWave&&seals.every(s=>!s.on)){finalWave=true;enemies.push(demon(15,4),demon(21,4),demon(18,6,1));tell('THE DEMON GATE OPENS! Climb to the northern cathedral.');combatAudio.stoneDoor()}}
function damage(n){p.hp=Math.max(0,p.hp-n);hurt=.45;tone(55,.18,'sawtooth',.12);if(!p.hp)finish(false)}
function collectItems(){for(let i of items){if(i.used||Math.hypot(i.x-p.x,i.y-p.y)>.6||Math.abs(floorAt(i.x,i.y)-p.z)>.35)continue;if(i.type==='health'&&p.hp===100)continue;i.used=true;if(i.type==='heavy'){ownsHeavy=true;ammo[2]+=180;weapon=2;tell('SECRET ARSENAL — HEAVY MACHINE GUN! [3]')}else if(i.type==='health'){p.hp=Math.min(100,p.hp+35);tell('Health +35')}else{ammo[0]+=24;ammo[1]+=8;if(ownsHeavy)ammo[2]+=60;if(i.type==='secret'){p.hp=Math.min(100,p.hp+25);tell('Secret stash — health and ammo!')}else tell('Ammo picked up')}tone(480,.16,'triangle')}}
function update(dt){time+=dt;cooldown=Math.max(0,cooldown-dt);flash=Math.max(0,flash-dt);hurt=Math.max(0,hurt-dt);notice-=dt;if(notice<=0)$('message').textContent='';let f=(keys.w||keys.z||mouse.right?1:0)-(keys.s?1:0),r=(keys.d?1:0)-(keys.a||keys.q?1:0),speed=(keys.shift?4.3:3.1)*dt/Math.max(1,Math.hypot(f,r));p.a=angle(p.a+((keys.arrowright?1:0)-(keys.arrowleft?1:0))*dt*2);move(p,(Math.cos(p.a)*f-Math.sin(p.a)*r)*speed,(Math.sin(p.a)*f+Math.cos(p.a)*r)*speed);p.eyeZ+=(p.z-p.eyeZ)*(1-Math.exp(-dt*14));p.pitch=clamp(p.pitch+((keys.arrowup?1:0)-(keys.arrowdown?1:0))*dt*1.3,-1.35,1.35);updateBlood(dt);updateSecrets(dt);activateSeals();if(keys[' ']||mouse.left)shoot();
 for(let e of enemies){if(e.hp<=0)continue;e.hit=Math.max(0,e.hit-dt);e.cd-=dt;let d=Math.hypot(p.x-e.x,p.y-e.y),visible=line(e.x,e.y,p.x,p.y,e.z+1.05,p.z+1.05);if(d<12&&visible){let a=Math.atan2(p.y-e.y,p.x-e.x);if(d>(e.type===1?3:.75))move(e,Math.cos(a)*dt*[1.4,.7,.7][e.type],Math.sin(a)*dt*[1.4,.7,.7][e.type]);if(e.cd<=0){if(e.type===1){let z=e.z+1.1,dz=p.z+1.05-z,length=Math.hypot(d,dz);shots.push({x:e.x,y:e.y,z,dx:Math.cos(a)*d/length*3.5,dy:Math.sin(a)*d/length*3.5,dz:dz/length*3.5});e.cd=2.3}else if(d<1&&Math.abs(e.z-p.z)<.6){damage(e.type===2?22:9);e.cd=.95}}}}
 for(let s of shots){s.x+=s.dx*dt;s.y+=s.dy*dt;s.z+=s.dz*dt;if(solid(s.x,s.y)||s.z<floorAt(s.x,s.y)+.05||s.z>ceilingAt(s.x,s.y))s.dead=true;if(Math.hypot(s.x-p.x,s.y-p.y)<.3&&Math.abs(s.z-(p.z+1))<.7){damage(12);s.dead=true}}shots=shots.filter(s=>!s.dead);collectItems();if(finalWave)gateProgress=Math.min(1,gateProgress+dt*.8);if(finalWave&&gateProgress>.9&&Math.hypot(p.x-exit.x,p.y-exit.y)<.85&&Math.abs(p.z-floorAt(exit.x,exit.y))<.35)finish(true);hud();
}
function hud(){$('health').innerHTML=Math.ceil(p.hp)+' <i>%</i>';$('healthbar').style.width=p.hp+'%';$('ammo').textContent=ammo?.[weapon]??0;$('weapon').textContent=WEAPONS[weapon].name;$('heavyhint').textContent=ownsHeavy?'[3] HEAVY MACHINE GUN':'[3] HIDDEN WEAPON';$('kills').textContent=kills+' DEMONS KILLED';$('seals').textContent=seals.map(s=>s.on?'◇':'◆').join(' ');$('secretcount').textContent=secretsFound+' / 2 SECRETS';$('timer').textContent=String(Math.floor(time/60)).padStart(2,'0')+':'+String(Math.floor(time%60)).padStart(2,'0');$('status').textContent=finalWave?'CLIMB TO THE DEMON GATE':'STEP ON THE THREE SEALS';$('sector').textContent=p.z>1.9?'UPPER CATHEDRAL':p.z< -1.4?'LOWER CRYPT':p.z!==0?'STONE STAIRWAY':'THE DAMNED COURTYARD';$('damage').style.opacity=hurt*.65}
function sprite(type){let c=document.createElement('canvas');c.width=c.height=64;let g=c.getContext('2d');const rect=(color,x,y,w,h)=>{g.fillStyle=color;g.fillRect(x,y,w,h)};if(typeof type==='number'){let color=['#ae4327','#814a58','#703124'][type];rect('#271713',15,52,13,10);rect('#271713',36,52,13,10);rect(color,16,25,32,29);rect(color,8,31,10,20);rect(color,46,31,10,20);rect('#e0b787',8,48,8,5);rect('#e0b787',48,48,8,5);rect(color,21,12,22,20);rect('#d0b49a',17,3,6,14);rect('#d0b49a',41,3,6,14);rect('#5b201b',24,30,16,19);rect('#f9b62b',24,19,5,4);rect('#f9b62b',35,19,5,4);rect('#160b09',26,27,12,4);rect('#efcca0',28,27,3,5);rect('#efcca0',34,27,3,5);if(type===2){rect('#caa88b',12,23,8,10);rect('#caa88b',44,23,8,10);rect('#ee6121',27,35,10,8)}if(type===1){rect('#ef692d',4,39,9,9);rect('#ffde73',6,41,5,5)}}else if(type==='seal'){g.strokeStyle='#f56a35';g.lineWidth=3;g.beginPath();g.arc(32,32,22,0,Math.PI*2);g.stroke();g.beginPath();for(let n=0;n<6;n++){let a=-Math.PI/2+n*4*Math.PI/5;let x=32+Math.cos(a)*19,y=32+Math.sin(a)*19;n?g.lineTo(x,y):g.moveTo(x,y)}g.stroke()}else if(type==='portal'){rect('#3c291e',8,2,48,62);rect('#5d5141',12,4,40,60);rect('#120d1c',18,10,28,54);rect('#ad4dd8',21,13,22,51);rect('#efd6ff',27,18,10,46)}else if(type==='fire'){rect('#d82e12',20,20,24,24);rect('#ff9b26',24,24,16,16);rect('#fff5aa',28,28,8,8)}else{rect(type==='health'?'#d3c6a5':'#847047',16,30,32,24);if(type==='health'){rect('#b13522',28,33,8,18);rect('#b13522',23,38,18,8)}else{rect('#e8b65b',21,34,5,13);rect('#e8b65b',30,34,5,13);rect('#e8b65b',39,34,5,13)}}return c}
const sprites={0:sprite(0),1:sprite(1),2:sprite(2),seal:sprite('seal'),portal:sprite('portal'),fire:sprite('fire'),health:sprite('health'),ammo:sprite('ammo'),secret:sprite('ammo')};
function render(){ctx.clearRect(0,0,W,H);if(!renderer?.ready)return;let objects=[...secretDoors.filter(d=>!d.opened).map(d=>({x:d.hintX,y:d.hintY,kind:'crack',wallDecal:true,height:.45,base:floorAt(d.hintX,d.hintY)+1.05})),...splats.map(b=>({...b,kind:'bloodstain',ground:true,opacity:Math.min(1,b.life/3)})),...particles.map(b=>({...b,kind:'blood',height:b.size,base:b.z})),...enemies.filter(e=>e.hp>0).map(e=>({...e,kind:e.type,height:e.type===2?2.2:1.65,base:e.z})),...items.filter(i=>!i.used).map(i=>({...i,kind:i.type,height:i.type==='heavy'?.7:.45,width:i.type==='heavy'?1:.45,base:floorAt(i.x,i.y)})),...seals.map(s=>({...s,kind:'seal',ground:true,size:1.25,base:floorAt(s.x,s.y)+.015,active:s.on,opacity:s.on?1:.25})),...shots.map(s=>({...s,kind:'fire',base:s.z-.16})),{...exit,kind:'portal',height:3.35,width:2.7,base:floorAt(exit.x,exit.y),active:finalWave,progress:gateProgress}];renderer.draw(p,objects,time);let moving=mode==='playing'&&(mouse.right||keys.w||keys.z||keys.s||keys.a||keys.q||keys.d),bob=moving?Math.sin(time*10)*5:0,recoil=flash/.14,size=WEAPONS[weapon].size,cx=W*.5+35,top=H*.54+bob+recoil*(weapon===2?12:26);ctx.imageSmoothingEnabled=true;ctx.drawImage(renderer.weapons[weapon],cx-size/2,top,size,size);if(flash>0){let mx=cx,my=top+size*.025;ctx.save();ctx.globalCompositeOperation='screen';let fire=ctx.createRadialGradient(mx,my,2,mx,my,weapon===2?95:80);fire.addColorStop(0,'#ffffe5');fire.addColorStop(.25,'#ffd65df0');fire.addColorStop(.6,'#f7632190');fire.addColorStop(1,'#ff450000');ctx.fillStyle=fire;ctx.fillRect(mx-95,my-95,190,190);ctx.restore()}if(mapShown)drawMap()}
function drawMap(){const scale=4.5,ox=12,oy=12;ctx.fillStyle='#0c0808ef';ctx.fillRect(8,8,WORLD_WIDTH*scale+8,WORLD_DEPTH*scale+8);for(let y=0;y<level.length;y++)for(let x=0;x<level[y].length;x++){ctx.fillStyle=solid(x,y)||hiddenMapCell(x,y)?'#79634c':floorAt(x,y)>1.9?'#735a36':floorAt(x,y)<-1.4?'#39283f':floorAt(x,y)!==0?'#b27c4b':'#211810';ctx.fillRect(ox+x*scale,oy+y*scale,scale-.5,scale-.5)}for(let s of seals){ctx.fillStyle=s.on?'#f47c32':'#685441';ctx.fillRect(ox+s.x*scale-2,oy+s.y*scale-2,4,4)}ctx.fillStyle=finalWave?'#f86323':'#674131';ctx.fillRect(ox+exit.x*scale-3,oy+exit.y*scale-3,6,6);ctx.fillStyle='#ffebad';ctx.beginPath();ctx.arc(ox+p.x*scale,oy+p.y*scale,3,0,7);ctx.fill();ctx.strokeStyle='#ffebad';ctx.beginPath();ctx.moveTo(ox+p.x*scale,oy+p.y*scale);ctx.lineTo(ox+(p.x+Math.cos(p.a))*scale,oy+(p.y+Math.sin(p.a))*scale);ctx.stroke()}
function pause(){if(mode!=='playing')return;mode='paused';combatAudio.stopVoice();combatAudio.setGameplayActive(false);keys={};mouse={left:false,right:false};$('veil').style.display='flex';$('crosshair').style.display='none';$('interact').textContent='';document.querySelector('.eyebrow').textContent='CATCH YOUR BREATH.';document.querySelector('h1').innerHTML='HELL<br><em>CAN WAIT</em>';$('description').textContent='The fortress is waiting. So are the demons.';$('play').textContent='RESUME →';$('hint').textContent='USE ARROW KEYS IF MOUSE CAPTURE IS UNAVAILABLE'}
$('play').onclick=()=>{if(mode!=='paused')reset();mode='playing';$('veil').style.display='none';$('crosshair').style.display='block';if(!audio)try{audio=new(window.AudioContext||window.webkitAudioContext)()}catch{}audio?.resume();combatAudio.init(audio);combatAudio.setMuted(!sound);combatAudio.setGameplayActive(true);try{canvas.requestPointerLock?.()?.catch(()=>tell('Mouse capture unavailable: use arrow keys.'))}catch{tell('Use arrow keys to look around.')}tell('Step on seals. E: secret walls. Find the heavy machine gun!')};
$('music').onclick=()=>{combatAudio.setMusicEnabled(!combatAudio.musicEnabled);$('music').textContent='MUSIC: '+(combatAudio.musicEnabled?'ON':'OFF');$('music').setAttribute('aria-pressed',String(combatAudio.musicEnabled))};
$('voice').onclick=()=>{combatAudio.setVoiceEnabled(!combatAudio.voiceEnabled);$('voice').textContent='VOICE: '+(combatAudio.voiceEnabled?'ON':'OFF');$('voice').setAttribute('aria-pressed',String(combatAudio.voiceEnabled))};
$('sound').onclick=()=>{sound=!sound;combatAudio.setMuted(!sound);$('sound').textContent='SOUND: '+(sound?'ON':'OFF')};
document.addEventListener('pointerlockchange',()=>{if(document.pointerLockElement!==canvas)pause()});document.addEventListener('mousemove',e=>{if(mode==='playing'&&document.pointerLockElement===canvas){p.a=angle(p.a+e.movementX*.0025);p.pitch=clamp(p.pitch-e.movementY*.0025,-1.35,1.35)}});canvas.addEventListener('mousedown',e=>{if(mode!=='playing')return;e.preventDefault();if(e.button===0){mouse.left=true;shoot()}if(e.button===2)mouse.right=true});document.addEventListener('mouseup',e=>{if(e.button===0)mouse.left=false;if(e.button===2)mouse.right=false});canvas.addEventListener('contextmenu',e=>e.preventDefault());document.addEventListener('keydown',e=>{let k=e.key.toLowerCase();if([' ','arrowleft','arrowright','arrowup','arrowdown'].includes(k))e.preventDefault();keys[k]=true;if(mode==='playing'){if(['1','2','3'].includes(k))selectWeapon(Number(k)-1);if(k==='e'&&!e.repeat)interact();if(k==='m'&&!e.repeat)mapShown=!mapShown;if(k==='escape'){pause();document.exitPointerLock?.()}}});document.addEventListener('keyup',e=>keys[e.key.toLowerCase()]=false);window.addEventListener('blur',()=>{pause();keys={};mouse={left:false,right:false}});document.addEventListener('visibilitychange',()=>{if(document.hidden)pause()});
function frame(t){let dt=Math.min((t-last)/1000,.04);last=t;if(mode==='playing')update(dt);render();requestAnimationFrame(frame)}reset();$('play').disabled=true;$('play').textContent='LOADING THE FORTRESS…';
try{renderer=new HellRenderer(canvas,level,floorAt,ceilingAt);renderer.load(sprites).then(()=>{$('play').disabled=false;$('play').textContent='ENTER HELL →';requestAnimationFrame(frame)}).catch(showLoadError)}catch(e){showLoadError(e)}
function showLoadError(e){$('description').textContent=e.message;$('play').textContent='RELOAD';$('play').disabled=false;$('play').onclick=()=>location.reload()}
